test('mergeCustomers moves invoices from fromId to intoId', () => {
  const customers = listCustomers();
  const invoices = [
    { id: 'INV-001', customerId: 'C-001', status: 'issued' },
    { id: 'INV-002', customerId: 'C-001', status: 'paid' },
    { id: 'INV-003', customerId: 'C-003', status: 'draft' },
  ];
  const r = mergeCustomers(customers, invoices, 'C-001', 'C-003');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, customers.length - 1);
  assert.equal(r.value.customers.some((c) => c.id === 'C-001'), false);
  assert.equal(r.value.invoices[0].customerId, 'C-003');
  assert.equal(r.value.invoices[1].customerId, 'C-003');
  assert.equal(r.value.invoices[2].customerId, 'C-003');
});

test('mergeCustomers rejects when fromId and intoId are the same', () => {
  const customers = listCustomers();
  const invoices = [];
  const r = mergeCustomers(customers, invoices, 'C-001', 'C-001');
  assert.deepEqual(r, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers rejects when fromId does not exist', () => {
  const customers = listCustomers();
  const invoices = [];
  const r = mergeCustomers(customers, invoices, 'C-999', 'C-001');
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers rejects when intoId does not exist', () => {
  const customers = listCustomers();
  const invoices = [];
  const r = mergeCustomers(customers, invoices, 'C-001', 'C-999');
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers does not mutate input arrays', () => {
  const customers = listCustomers();
  const invoices = [
    { id: 'INV-001', customerId: 'C-001' },
    { id: 'INV-002', customerId: 'C-003' },
  ];
  const originalCustomersLength = customers.length;
  const originalInvoicesLength = invoices.length;
  const originalInvoice1CustomerId = invoices[0].customerId;

  mergeCustomers(customers, invoices, 'C-001', 'C-003');

  assert.equal(customers.length, originalCustomersLength);
  assert.equal(invoices.length, originalInvoicesLength);
  assert.equal(invoices[0].customerId, originalInvoice1CustomerId);
});

test('mergeCustomers normalizes customer IDs before comparing', () => {
  const customers = listCustomers();
  const invoices = [{ id: 'INV-001', customerId: 'C-001' }];
